type Interval = { start: number; end: number };
export function available(slot: Interval, busy: Interval[], bufferMs = 0) {
  if (slot.start >= slot.end || bufferMs < 0) return false;
  return busy.every(item =>
    slot.end + bufferMs <= item.start || slot.start >= item.end + bufferMs
  );
}
