type Offer = { userId: string; expiresAt: number; acceptedAt: number | null };
export function mayAccept(offer: Offer, userId: string, now: number) {
  return offer.userId === userId && offer.acceptedAt === null
    && now < offer.expiresAt;
}
// 이 판정과 좌석 확정은 같은 서버 트랜잭션에서 수행합니다.

type BookingState = 'confirmed' | 'cancelled';
export function cancel(state: BookingState, now: number, cutoff: number) {
  if (state === 'cancelled') return state;
  if (now >= cutoff) throw new Error('취소 가능 시간이 지났습니다.');
  return 'cancelled' as const;
}
// 정책 시간은 서버에서 읽고 환불 결과는 별도 필드에 기록합니다.

type EventLink = { bookingId: string; externalId: string; version: number };
export function needsSync(link: EventLink, bookingVersion: number) {
  return bookingVersion > link.version;
}
export function mappingKey(provider: string, calendarId: string, eventId: string) {
  return JSON.stringify([provider, calendarId, eventId]);
}

export function formatInZone(iso: string, timeZone: string) {
  const date = new Date(iso);
  if (!Number.isFinite(date.getTime())) throw new Error('잘못된 시각');
  return new Intl.DateTimeFormat('ko-KR', {
    dateStyle: 'medium', timeStyle: 'short', timeZone
  }).format(date);
}
